use super::*;
use crate::{json,original_group_game};use super::super::effects::{self,Kind};
fn field(orientation:i16)->Game{let mut g=Game::new(0,1,818);g.map.original=true;g.map.width=64;g.map.height=64;g.map.tiles=vec![0;4096];g.map.terrain_codes=vec![0;4096];g.map.native_terrain_plane=vec![0;16384];g.map.original_tiles=vec![0;4096];g.map.native_tile_plane=vec![0;16384];g.map.bridge_base=vec![-1;4096];g.map.bridge_hp=vec![200.];g.map.bridge_max_hp=vec![200.];g.units.clear();g.buildings.clear();g.objects.clear();g.crates.clear();g.walls.clear();g.sectors.clear();g.ai_teams.clear();g.native_world=None;g.native_strategy=None;g.native_group_rosters=original_group_game::State::default();g.import_native_world(&json!({"bridges":[{"id":0,"nativeSlot":0,"nativeOrientation":orientation,"x":640,"y":640,"w":192,"h":192,"hp":200,"maxHp":200}]}));g.native_view=Some(([0,0],[640,480]));g.native_feedback.sound_enabled=1;g.native_feedback.ui_clock=120;g}
fn source(sprite:i16)->Particle{let mut p=effects::initialize(Kind::Destroyed,[200,200],0,||0);p.expiry=11;p.lifetime=0;p.sprite=sprite;p.maximum_phase=11;p}
#[test]fn half_health_prefix_uses_two_middle_lanes_all_five_worlds_and_restores_suppression(){
 for world in 0..5{for orientation in[0,1]{let mut g=field(orientation);g.map.world=world;let s=g.native_world.as_mut().unwrap();s.effect_tint=73;s.effect_suppression=1;s.bridge_fx=native::Raw{byte32:0xa5,payload36:0x1000,payload40:0x2000,command:0xabcd1234,..Default::default()};s.effect_cp_tints.fill(Some(1));let mut rng=g.original_rng.clone();for _ in 0..40{rng.next_u32();}g.damage_native_bridge([320,320],100,0);assert_eq!(g.original_rng.words,rng.words);let s=g.native_world.as_ref().unwrap();let particles=s.effects.iter().flatten().filter(|p|p.active).collect::<Vec<_>>();assert_eq!(particles.len(),8);let sprite=native::engine_sprites(world).unwrap().prefix;for(i,p)in particles.iter().enumerate(){assert_eq!((p.sprite,p.expiry,p.maximum_phase,p.owner,p.flags,p.lifetime),(sprite,11,11,0,12,500));let origin=if orientation==0{[176+(i/2)as i16*16,320-[92,76][i%2]]}else{[320-[144,128][i%2],228+(i/2)as i16*16]};assert_eq!(p.origin,origin);let b=p.bytes();assert_eq!(b[32],0xa5);assert_eq!(&b[36..40],&(0x1000+i as u32*10).to_le_bytes());assert_eq!(&b[40..44],&0x2000u32.to_le_bytes());assert_eq!(p.tint,73);assert!(s.effect_cp_tints[i].is_none());}assert_eq!(s.bridge_fx.payload36,0x1050);assert_eq!(s.bridge_fx.command,0xabcd064a);assert_eq!(s.bridge_fx.last_record,Some(native::NATIVE_POOL+7*44));assert_eq!(s.effect_suppression,1);assert_eq!(g.native_audio.explosion_cycle,0);let before=g.original_rng.words;g.damage_native_bridge([320,320],1,0);assert_eq!(g.original_rng.words,before,"already-half bridge cannot replay its prefix");}}
}
#[test]fn full_pool_prefix_advances_payload_per_attempt_without_rng_and_keeps_unknown_pointer_unknown(){
 let mut g=field(0);let p=effects::initialize(Kind::Hit,[0,0],0,||0);let s=g.native_world.as_mut().unwrap();s.effects.fill(Some(p));s.effect_suppression=255;s.bridge_fx.payload36=0xfffffff0;s.bridge_fx.last_record=None;let before=g.original_rng.words;g.damage_native_bridge([320,320],255,0);assert_eq!(g.original_rng.words,before);let s=g.native_world.as_ref().unwrap();assert_eq!(s.bridge_fx.payload36,0x90);assert_eq!(s.bridge_fx.last_record,None);assert_eq!(s.bridge_fx.constructor,Some(native::BRIDGE_CONSTRUCTOR));assert_eq!(s.effect_suppression,255);assert_eq!(s.effects.iter().flatten().filter(|p|p.active).count(),500);let sound=g.events.iter().position(|e|e["kind"]=="nativeSample").unwrap();let dead=g.events.iter().position(|e|e["kind"]=="bridgeDestroyed").unwrap();assert!(sound<dead);
}
#[test]fn short_bridge_only_writes_the_verified_prefix_globals_and_preserves_raw_context_over_import(){
 let mut g=field(0);let mut s=g.native_world.take().unwrap();s.effect_owner=3;s.effect_maximum=99;s.effect_flags=7;s.effect_suppression=1;s.bridge_fx=native::Raw{byte32:0xa7,payload36:0x12345678,payload40:0xabcdef01,command:0xcafe1234,last_record:None,constructor:Some(0x12345678)};let before=g.original_rng.words;g.native_bridge_particle_prefix(&mut s,Bridge{position:[300,400],size:[32,48],hp:1,maximum:200,flags15:0},0,false);assert_eq!(g.original_rng.words,before);assert_eq!((s.effect_owner,s.effect_maximum,s.effect_flags,s.effect_suppression),(0,12,7,1));assert_eq!(s.bridge_fx.command,0xcafe064a);assert_eq!(s.bridge_fx.last_record,None);assert_eq!(s.bridge_fx.constructor,Some(0x12345678));let raw=s.bridge_fx;g.native_world=Some(s);g.import_native_world(&json!(null));assert_eq!(g.native_world.as_ref().unwrap().bridge_fx,raw,"no source reset writer for these payload globals was proved");
}
#[test]fn expiry_draws_one_count_rng_even_full_or_disabled_and_only_then_retires_source(){
 for world in 0..5{for disabled in[0,1]{let mut g=field(0);g.map.world=world;let sprites=native::engine_sprites(world).unwrap();let p=source(sprites.prefix);let s=g.native_world.as_mut().unwrap();s.effects.fill(Some(p));s.effect_suppression=disabled;s.effect_tint=71;s.bridge_fx.last_record=Some(0xdeadbeef);let before=s.effects[17].as_ref().unwrap().bytes();let mut rng=g.original_rng.clone();rng.next_u32();g.finish_native_bridge_expiry(17);assert_eq!(g.original_rng.words,rng.words);let s=g.native_world.as_ref().unwrap();let after=s.effects[17].as_ref().unwrap().bytes();assert_eq!(&after[2..],&before[2..]);assert_eq!(&after[..2],&(-1000i16).to_le_bytes());assert_eq!(s.effects.iter().flatten().filter(|p|p.active).count(),499);assert_eq!(s.effect_sprite,sprites.children[1]);assert_eq!((s.effect_maximum,s.effect_flags,s.effect_fade,s.effect_owner,s.effect_tint),(5,4,0,0,71));assert_eq!(s.bridge_fx.last_record,Some(0xdeadbeef));}}
}
#[test]fn expiry_partial_second_group_preserves_raw_bytes_and_uses_world_sprites_not_generic250(){
 let mut g=field(0);g.original_rng=OriginalRng{words:[1,2,3,4,5],multiplayer:false};let mut rng=g.original_rng.clone();let count=4+(rng.next_u32()&3)as usize;let free=count+2;for _ in 0..free*6{rng.next_u32();}let mut old=[0xa5;44];old[..2].copy_from_slice(&(-1000i16).to_le_bytes());let s=g.native_world.as_mut().unwrap();s.effects=vec![Some(Particle::from_bytes(old));free+1];s.effects[0]=Some(source(1138));s.effect_tint=99;s.last_projection=[32767,-32768];s.bridge_fx.byte32=0x34;s.bridge_fx.payload36=0x12345678;s.bridge_fx.payload40=0x90abcdef;s.effect_cp_tints.fill(Some(1));g.finish_native_bridge_expiry(0);assert_eq!(g.original_rng.words,rng.words);let s=g.native_world.as_ref().unwrap();assert!(!s.effects[0].as_ref().unwrap().active);for i in 0..free{let p=s.effects[i+1].as_ref().unwrap();assert_eq!(p.sprite,if i<count{1578}else{1586});assert_eq!((p.flags,p.maximum_phase,p.tint,p.expiry,p.lifetime),(4,5,99,0,200));let b=p.bytes();assert_eq!(&b[34..36],&[0xa5,0xa5]);assert_eq!(b[32],0x34,"raw4a6522 is not inferred from projection high bits");assert_eq!(b[33],0);assert_eq!(&b[36..40],&0x12345678u32.to_le_bytes());assert_eq!(&b[40..44],&0x90abcdefu32.to_le_bytes());assert!(s.effect_cp_tints[i+1].is_none());}assert_eq!(s.bridge_fx.last_record,Some(native::NATIVE_POOL+free as u32*44));
}
#[test]fn expiry_children_follow_the_existing_live_slot_scan_and_keep_late_fx_draws(){
 for slot in[0,11]{let mut g=field(0);let s=g.native_world.as_mut().unwrap();s.effects=vec![None;12];s.effects[slot]=Some(source(1138));s.last_projection=[160,100];let mut rng=g.original_rng.clone();let count=4+(rng.next_u32()&3)as usize;for _ in 0..(count+4)*6{rng.next_u32();}g.update_native_world_effects();assert_eq!(g.original_rng.words,rng.words);let rows=g.native_world_effects();assert_eq!(rows.len(),if slot==0{count+4}else{0});for row in rows{assert_eq!(row["x"],736);assert_eq!(row["y"],632);assert!(row.get("primitive").is_none());let sprite=row["sprite"].as_i64().unwrap();assert!((1578..=1581).contains(&sprite)||(1586..=1589).contains(&sprite));}if slot==11{assert!(g.native_world.as_ref().unwrap().effects[..11].iter().flatten().all(|p|p.lifetime==200));g.update_native_world_effects();assert_eq!(g.native_world_effects().len(),count+4);}}
}
#[test]fn actual_main_draws_bridge_births_and_their_expiry_children_in_the_late_pass(){
 let mut g=field(0);g.spawn("grunt",0,100.,100.,1,None);g.spawn("grunt",1,1600.,1600.,2,None);g.damage_native_bridge([320,320],100,0);g.step(0.059);let rows=g.native_world_effects();assert_eq!(rows.len(),8);assert!(rows.iter().all(|r|(1138..=1141).contains(&r["sprite"].as_i64().unwrap())));assert!(rows.iter().all(|r|r["scale"]==0.5));for p in g.native_world.as_mut().unwrap().effects.iter_mut().flatten().filter(|p|p.expiry==11){p.lifetime=0;}g.step(0.059);assert!(g.native_world_effects().iter().any(|r|(1578..=1591).contains(&r["sprite"].as_i64().unwrap())));assert!(g.native_display_queue().iter().all(|r|r["draw"]["sprite"]!=1138),"500-pool effects remain in their late native pass");
}
#[test]fn optional_all_5120_native_vectors_also_match_the_actual_typed_game_pool(){
 let root=std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../../work/parity-audit");let mut g=field(0);let hash=|s:&State|{let mut h=2166136261u32;for p in &s.effects{for b in p.as_ref().unwrap().bytes(){h=(h^u32::from(b)).wrapping_mul(16777619);}}h};let hex=|b:[u8;44]|b.iter().map(|n|format!("{n:02x}")).collect::<String>();
 for(mode,name)in[(0,"v40-bridge-prefix.jsonl"),(1,"round40-bridge-expiry.jsonl")]{let Ok(csv)=std::fs::read_to_string(root.join(name))else{return;};let mut count=0;for line in csv.lines(){let r:serde_json::Value=serde_json::from_str(line).unwrap();let n=|k:&str|r[k].as_i64().unwrap();let scenario=n("scenario")as usize;let cap=n("capacity")as usize;let pattern=n("pattern");let source=if mode==1{Some(n("source")as usize)}else{None};g.map.world=[0,2,4,1,3][n("world")as usize];g.multiplayer=n("mp")!=0;g.original_rng=OriginalRng{words:std::array::from_fn(|i|0x173510a7u32.wrapping_add(scenario as u32*7919).wrapping_add((i as u32).wrapping_mul(0x9e3779b9))),multiplayer:g.multiplayer};let s=g.native_world.as_mut().unwrap();s.effects=(0..500usize).map(|slot|{let mut b=std::array::from_fn(|j|(scenario*17+slot*13+j*19)as u8);let free=match pattern{0=>false,1=>true,2=>slot==0,3=>slot==cap.wrapping_sub(1),4=>slot%2==0,5=>[1,7,31,99,499].contains(&slot),6=>slot<7,_=>slot<10};b[..2].copy_from_slice(&(if free{-1000i16}else{[0,-1,999][slot%3]}).to_le_bytes());if source==Some(slot){b[..2].fill(0);b[6..8].copy_from_slice(&(n("ox")as i16).to_le_bytes());b[8..10].copy_from_slice(&(n("oy")as i16).to_le_bytes());}Some(Particle::from_bytes(b))}).collect();s.effect_origin=[-1234,2345];s.effect_tint=(scenario*31)as u8;s.effect_flags=if mode==0{7}else{12};s.effect_fade=3;s.effect_owner=3;s.effect_sprite=557;s.effect_maximum=99;s.effect_suppression=n("gate")as u8;s.bridge_fx=native::Raw{byte32:(scenario*23)as u8,payload36:if mode==0{n("inputPayload")as u32}else{0x1800000+scenario as u32*40},payload40:0x1900000+scenario as u32*44,command:if mode==0{0xabcd1234}else{0},last_record:Some(0xdeadbeef),constructor:Some(0x12345678)};assert_eq!(hash(s),n("before")as u32);
  if mode==0{let orientation=n("orientation")as i16;let span=n("span")as i16;let bridge=Bridge{position:[n("x")as i16,n("y")as i16],size:if orientation==0{[span,48]}else{[48,span]},hp:1,maximum:200,flags15:0};if cap==500{let mut state=g.native_world.take().unwrap();g.native_bridge_particle_prefix(&mut state,bridge,orientation,n("half")!=0);g.native_world=Some(state);}else{let state=g.native_world.as_mut().unwrap();let mut ctx=globals(state);native::prefix(&mut World{state,rng:&mut g.original_rng,limit:cap},&mut ctx,bridge.position,bridge.size,orientation,n("half")!=0,n("worldSprite")as i16);commit(state,ctx);}}
  else{g.native_world.as_mut().unwrap().last_projection=[n("px")as i16,n("py")as i16];if cap==500{g.finish_native_bridge_expiry(source.unwrap());}else{let state=g.native_world.as_mut().unwrap();let mut ctx=globals(state);let projection=state.last_projection;native::expiry(&mut World{state,rng:&mut g.original_rng,limit:cap},&mut ctx,source.unwrap(),projection,[n("sprite1")as i16,n("sprite2")as i16]);commit(state,ctx);}}
  let s=g.native_world.as_ref().unwrap();assert_eq!(hash(s),n("hash")as u32,"{name} scenario{scenario}: all500x44");assert_eq!(g.original_rng.words,std::array::from_fn(|i|n(&format!("r{i}"))as u32));assert_eq!(s.effect_origin,[n("originX")as i16,n("originY")as i16]);assert_eq!((s.effect_tint,s.effect_maximum as u8,s.effect_flags,s.effect_fade,s.effect_owner,s.effect_sprite),(n("tint")as u8,n("maximum")as u8,n("flags")as u8,n("fade")as u8,n("owner")as u8,n("sprite")as i16));assert_eq!(s.bridge_fx.constructor,Some(n("constructor")as u32));assert_eq!(s.bridge_fx.last_record,Some(n("queuePointer")as u32));assert_eq!((s.bridge_fx.payload36,s.bridge_fx.payload40),(n("payload36")as u32,n("payload40")as u32));for k in["first","last"]{let slot=n(k);if slot>=0{assert_eq!(r[format!("{k}Bytes")],hex(s.effects[slot as usize].as_ref().unwrap().bytes()));}}if let Some(slot)=source{assert_eq!(r["sourceBytes"],hex(s.effects[slot].as_ref().unwrap().bytes()));}count+=1;
 }assert_eq!(count,2560);}
}
